<script setup lang="ts">import type { PublicFormField } from '~/types/public-form'; defineProps<{field:PublicFormField;modelValue:unknown;error?:string}>();defineEmits<{(e:'update:modelValue',v:unknown):void}>()</script>
<template><div class="space-y-1"><BaseInput v-if="['TEXT','EMAIL','PHONE','DATE','HIDDEN'].includes(field.type)" :type="field.type==='DATE'?'date':field.type==='EMAIL'?'email':'text'" :label="field.label" :placeholder="field.placeholder" :model-value="String(modelValue||'')" :error="error" @update:model-value="$emit('update:modelValue',$event)"/><BaseTextarea v-else-if="field.type==='TEXTAREA'" :label="field.label" :model-value="String(modelValue||'')" @update:model-value="$emit('update:modelValue',$event)"/><BaseSelect v-else :label="field.label" :model-value="String(modelValue||'')" :options="(field.options||[]).map((o)=>({label:o,value:o}))" @update:model-value="$emit('update:modelValue',$event)"/></div></template>
